package app

// More of what free-form fields hold (native_operation_field_shapes.go): a
// database automation's trigger and steps (a button's steps are the same
// document), an app's action input and stored value, a form's answers and a
// comment's text, as the screen writes them.

var nativeOperationMoreFieldShapes = map[string]string{
	// A database automation ("자동화"), POST /pages/{pageId}/databases/{databaseId}/automations.
	"databaseautomationdefinitioninput.trigger":        `When an automation runs ("트리거"). On changes: {"type": "events", "mode": "any" or "all" (one condition, or every one), "conditions": [{"type": "row_added"} ("페이지 추가됨") or {"type": "property_edited", "propertyId", "operator", "value"} ("속성 편집됨"; without propertyId, any property's edit, with no operator or value)]}. On a schedule ("매일", "매주"…): {"type": "schedule", "frequency": "daily" (interval up to 365), "weekly" (up to 52, with "weekdays": [0–6, Sunday 0]), "monthly" (up to 24, with "monthDay" 1–31, or "monthWeek" 1–5 (5 the last) and one weekday) or "yearly" (up to 10), "interval": how many apart (1 is every), "time": "HH:MM" or "midnight", "timeZone": an IANA zone such as "Asia/Seoul", "startsOn": "YYYY-MM-DD", and "endsOn" or "endsAfter" (runs, up to 999) or neither}; a schedule's steps don't use edit_property. Property ids are the ones GET /pages/{id}/content-graph names.`,
	"databaseautomationdefinitioninput.mutationid":     `An id of yours for this change: the same request sent again with it isn't done twice (left out, the server makes one, new each time). In the path, {pageId} is the page that holds the database and {databaseId} its data source. An edit (PATCH …/automations/{automationId}) sends only what changes, with "expectedRevision": the automation's revision as GET …/automations lists it.`,
	"databaseautomationtriggercondition.value":         `What the edited property must hold after the edit, by "operator": none names no value (any change), "cleared" (emptied) none; "is", "is_not", "contains", "does_not_contain" a text, a number, or a list of option ids, person ids, page ids or true/false for a checkbox (none: any value); "starts_with", "ends_with" a text; "greater_than", "less_than", "greater_or_equal", "less_or_equal" a number. Text compares without case.`,
	"databaseautomationdefinitioninput.actiondocument": `What runs, in order ("작업"), the document a button's actions are too: {"version": 1, "label" (optional), "actions": [steps, each {"id": unique in the document, "type", …}]}. An automation's steps: "define_variables" {"variables": [{"name", "value"}]}; "edit_property" {"target": "trigger_page", "propertyId", "value"} (the page that set it off); "add_page" {"target": "database", "databaseId": the data source, "title", "templateId" (optional), "properties": [{"propertyId", "value"}]}; "edit_pages" {"target", "changes": [{"propertyId", "value"}]}; "archive_pages" {"target"} (archives the pages it names, "페이지 보관하기…"); "set_page_icon" {"target": "trigger_page", "icon", "iconType": "emoji", "icon" (a built-in icon's name, as a page's) or "custom_emoji" (the workspace emoji's id)} (sets the icon of the page that set it off, "페이지 아이콘 편집…"; not for a schedule); "send_notification" {"recipientIds": up to 20 user ids and/or "recipientSources", with "message", "messageSpans" or "messageFormula"}; "send_email" {"recipientEmail", "subject", "message"}; "send_webhook" {"url": a public https address, "propertyIds": the properties it sends, "headers": [{"name", "value"}]}; "send_slack" {"connectionId", "channelId", "message"}; "run_app_action" {"appInstallId", "appAction": the action's key, "appInput"}. Only a button also has "insert_blocks" {"target": "trigger_page", "blocks", "placement": "button_above", "button_below", "page_top" or "page_bottom"}, "show_confirmation" {"title", "message", "confirmLabel", "cancelLabel"}, "open_page" {"pageId" (a page, or a database a page holds by its block's ID), or "target": "trigger_page"; "openIn": "side_peek", "center_peek" or "full_page"}, "open_form" {"databaseId", "viewId"} and "open_url" {"url"}. Each "value" is interactiveautomationvalueexpression.value's.`,
	"interactiveautomationaction.target":               `Which pages a step acts on: "trigger_page" (the page that set it off, or the row whose button was pressed) for edit_property, set_page_icon, insert_blocks and open_page; "database" for add_page; for edit_pages and archive_pages {"type": "database", "databaseId", "filter": a database query's filter group (database-query's DatabaseQueryFilterGroup: {"conjunction": "and" or "or", "filters": [...]}, {} for every page), "timeZone"} or {"type": "this_page", "databaseId"} (the row whose button was pressed, or the page that set off an automation's run; not for a schedule).`,
	"interactiveautomationaction.title":                `add_page's title: a plain string, or a value (interactiveautomationvalueexpression.value: {"kind": "literal", "value": "…"}, a formula or a variable). show_confirmation's title: a string.`,
	"interactiveautomationaction.appinput":             `run_app_action's input for the app's action, an object as the action's input schema says (leafen_app_tools with the app lists each tool's inputSchema; its name is appAction). Only an action that doesn't ask for approval runs from an automation or button, and none where the administrator oversees the organization's apps.`,
	"interactiveautomationrecipientsource.kind":        `Who else a notification goes to: "execution_actor" (who set it off or pressed the button), "page_creator" (who made the page), "person_property" with "propertyId" (the people a person property names), or "formula" with "expression".`,
	"interactiveautomationvalueexpression.value":       `A value a step sets, by "kind": "literal" with "value" the property's cell value (graphrowvalue.value: an option's id for a select, a list of user ids for a person, where {"source": "execution_actor"} or {"source": "page_creator"} names who ran it or made the page; a list of page ids for a relation, where {"source": "trigger_page"} names the page the run starts from), "mode": "add", "remove" or "toggle" to change a person, relation or multi-select's items instead of replacing them, and "spans" for text with mentions; "variable" with "name"; "trigger_property" with "propertyId" (the triggering page's value); "execution_time" or "execution_date" (when it runs); "formula" with "expression" (prop("Name") reads the triggering page).`,
	"interactiveautomationblocktemplate.content":       `A block insert_blocks adds: "type" a block type (not a page or database), "content" its content as a content graph block keeps it ({"text": "…"} and its formatting as "rich": text spans, for a text block; leafen_operations' content-graph mutations list each type's in block_contents), "children" blocks under it.`,
	// An app's action and stored values, POST /apps/{installId}/actions/{action} and /storage.
	"appactioninput.input":    `The action's input, an object as the app's input schema for it says. This route is the app's own screen's, which an agent's key doesn't run (LEAFEN_APP_RELAY_DENIED): an agent runs the same action as a tool with leafen_app_call {"app": its slug, "tool": the action, "input"}, and leafen_app_tools with the app lists each tool's inputSchema; one that needs approval asks the person in the conversation.`,
	"appstoragerequest.value": `For "set", any JSON value the app's screen keeps under "key" for this person (the screen's own settings); "get" and "remove" take only "key", "keys" neither. Add "?tenancy=" for an app used in more than one organization.`,
	// A form's answers, POST /forms with action "submit".
	"formsubmitrequest.answers": `The answers by question, keyed by the question's propertyId: POST /forms {"action": "definition", "token"} gives the form's questions, its properties and its "revision" to send back (the token is the one in the form's link, /forms/{token}; a member who may edit the database gets it as formLink.token from POST /forms {"action": "configure", "mutationId", "pageId", "dataSourceId", "viewId", "audience": the view config's leafenFormAudience, "form": its leafenForm}, as GET /pages/{pageId}/content-graph reads the view). Each answer by its property's type: title, text and phone a string; url an http(s) address; email an address; number a number; checkbox true or false; select and status an option's id (properties[].config.options); multi_select a list of option ids (up to the question's maxSelections); person and relation a list of user or page ids (POST /forms {"action": "options", "token", "propertyId", "revision"} lists them); date "YYYY-MM-DD", "YYYY-MM-DDTHH:MM" where the question includes the time, or {"start", "end"} where it includes an end; place {"lat", "lon", "name", "address"}; files the ids of files uploaded for that question. Leave out a question a condition hides; a required one needs an answer. "requestId" makes a retry safe.`,
	// A form's questions and their conditions, POST /forms with action
	// "configure" (2026-11-25: "양식 질문 숨기기" found the form's answers by a
	// question their description says a condition hides).
	"formconfigurerequest.form": `The form's questions and their conditions, as GET /pages/{pageId}/content-graph reads them (leafenForm); send it whole, changed. Its "questions" in order ("position" from 0), one a property, each {"id", "propertyId", "label", "description", "required", "hidden": true for a question those answering don't see (one not required), "conditionGroupId": asked only while its condition holds}; its "conditionGroups", the form editor's "조건부 로직", each {"id", "sourceQuestionId": a choice question's (select, multi_select, status) with "optionIds", any of them chosen or all with "matchAll": true, or a checkbox question's with "checked"}.`,
	// A block's place, POST /pages/{pageId}/content-graph/mutations.
	"graphblock.position": `Optional for a block: leave it out and a new block goes right after afterId, or last under its parent (parentId, null for the page) when afterId is null, as Notion's "after" places one; a moveBlock is placed the same way by parentId and afterId alone. A stored block keeps its place unless parentId or afterId moves it. Views, properties and rows take one: a place that sorts as text among their siblings' (GET /pages/{pageId}/content-graph reads theirs); one sorting after the last puts it last.`,
	// A comment's text, POST /pages/{pageId}/comments and its edits.
	"commentbody.rich":      `The comment's text as runs, each {"text": "…"} with what marks it: "bold", "italic", "code", "link"; a person mentioned is a run {"text": "@Name", "mention": "person", "userId"} and is notified; a page is {"text": its title, "mention": "page", "pageId"}. A reply names the first comment as parentId; a comment on a block names blockId, and on part of its text "quote", "quoteStart" and "quoteEnd" too.`,
	"commentcreateinput.id": `A new id of yours for the comment, required (up to 160 characters), and "requestId" another, so the same request sent again isn't posted twice; "parentId" for a reply, "blockId" for a comment on a block. A database row's page takes its comments at /pages/{rowId}/comments as any page does, or at /database-rows/{rowId}/comments (the row's id is its page's).`,
	"commentrecord.body":    `The comment's body as CommentBody: "rich" (its text runs, commentbody.rich), "attachmentIds", and where it is anchored ("quote", "quoteStart", "quoteEnd", "quoteBlocks", "propertyId").`,
	// An edit suggestion ("편집 제안"), POST /pages/{pageId}/suggestions.
	"suggestioncreateinput.kind":         `What the suggestion does to the text block blockId: "insert" puts text in at offset (length 0, text what goes in, marks optional); "delete" covers length units from offset (no text, no marks); "replace" suggests text (marks optional) in place of length units from offset — they are suggested away and the text goes in before them, one suggestion; "format" suggests marks on them (no text, marks such as {"bold": true}); "block" suggests a new block after the text (offset its end, newBlockId and blockType); "split" breaks the text at offset into newBlockId. id and requestId are new ids of yours, and expectedText is required.`,
	"suggestioncreateinput.expectedtext": `Required: the block's whole text as it is now, other suggestions' inserted text included (a delete after an insert includes what the insert put in). offset and length count its UTF-16 units and fall within it. If the text isn't that, the answer is 409 LEAFEN_COMMENT_SUGGESTION_TEXT_CHANGED with the block's text as it is: send that as expectedText.`,
	// A page's details, PATCH /pages/{id}/metadata.
	"pagemetadatainput.mutationid": `An id of yours for this change, so the same change sent again isn't made twice (left out, the server makes one, new each time), with "baseCursor", required: the page's cursor as GET /pages/{id} reads it (a change made meanwhile answers 409 LEAFEN_CURSOR_CONFLICT: read it again). Send only what changes (font, smallText, fullWidth, isLocked, icon …): what is left out stays.`,
	// A page's version restored or a change undone, POST /pages/{pageId}/history/{versionId}/restore and /revert.
	"pagehistoryrestorerequest.baserevision": `Required: the page's version history as it stands, snapshotFrontier as GET /pages/{pageId}/history reads it (or a restore's receipt gives it after); a change made meanwhile answers 409 LEAFEN_PAGE_HISTORY_REVISION_CHANGED: read it again.`,
	"pagehistoryrevertrequest.baserevision":  `Required: the page's version history as it stands, snapshotFrontier as GET /pages/{pageId}/history reads it; a change made meanwhile answers 409 LEAFEN_PAGE_HISTORY_REVISION_CHANGED: read it again.`,
	// What a field left as "unknown" holds, for each one an agent may send
	// (the user, 2026-11-26: an agent saw a tool's name and not what to give
	// it, and learned it only from a refusal). A database query's condition,
	// POST /pages/{pageId}/database-query.
	"databasequeryfilter.value": `What the condition compares the property with, by its type: a text (title, text, url, email, phone, a formula's or rollup's text); a number (number, unique id); true or false (checkbox); an option's id or name, or a list of them (select, multi_select; status also takes a status group's name); a list of user ids (person, created_by, last_edited_by; {"kind": "leafen.current_user"} for whoever queries) or page ids (relation; {"kind": "leafen.current_page"} for the page it runs on); a day "YYYY-MM-DD", with a time if it has one (date and the times), {"start", "end"} with is_between, or with relative_to_today {"direction": "this", "past" or "next", "unit": "day", "week", "month" or "year", "count"}; nothing with is_empty and is_not_empty. operator: equals, does_not_equal, contains, does_not_contain, starts_with, ends_with, greater_than, less_than, greater_than_or_equal_to, less_than_or_equal_to, before, after, on_or_before, on_or_after, is_between, relative_to_today, is_empty or is_not_empty, as the type takes them.`,
	// A template's body, createTemplate or updateTemplate.
	"databasetoolbarconfigmutationoperation.blocks": `The template's whole body, replacing it: a list of blocks, each {"id": a new id of yours, unique in the body, "parentId": another block's id or null for the top, "position": a place that sorts as text among its siblings', "type": a block type, "content": its content as a content graph block keeps it (POST /pages/{id}/content-graph/mutations' block_contents gives each type's)}. notion-update-page on the template's id writes its body in Markdown instead.`,
	// A database page's wiki title, POST /pages/{pageId}/wiki-page.
	"databaserowpagewikichangeinput.titlespans": `The new title's text as runs that spell it, each {"text": "…"} with what marks it: "bold", "italic", "underline", "strikethrough", "code", "color", "background", "link"; a mention is a run with "mention": "page" with "pageId", "database" with "databaseId", "person" with "userId", or "date" with "date".`,
	// My Tasks' views, PUT /workspaces/{workspaceId}/my-tasks/views.
	"body.views": `All of My Tasks' views, replacing them, as GET answers them (read them first and send them back changed): each {"id", "type": a view type such as "table" or "board", "config": its settings as a database view's (graphview.config), its "rowPlaces" keeping the tasks' order}, up to the screen's number of views.`,
	// A teamspace's change, POST /workspaces/{workspaceId}/teamspace-mutations:
	// each action's own needs, which the record marks for none.
	"teamspacemutationinput.action": `What the change does, with what each needs (the rest left out). "create": name, access ("open", "closed" or "private"), memberPageRole ("view", "comment", "edit" or "full_access") and openPageRole (those or "none"), membersCanInvite and membersCanEditSidebar (true or false), and optionally icon, description, disablePublishing, disableGuests and disableExport; no teamspaceId, and expectedRevision 0 (the new id is given back). "update": teamspaceId and expectedRevision (its revision as read, 1 or more) with all of create's settings. "join", "leave", "archive", "restore", "delete": teamspaceId and expectedRevision ("join" takes an inviteToken too, "request" a joinMessage). "respond": those with joinRequestId and joinResponse ("approved" or "denied"). "add_member", "update_member", "remove_member": those with principalType ("user" or "group"), principalId and, but for remove, memberRole ("owner" or "member"). "update_settings": ownersOnlyCreate and expectedRevision (the workspace's teamspace settings revision), no teamspaceId. "set_default": teamspaceId, expectedRevision and defaultTeamspaceId the same id. "set_defaults": defaultTeamspaceIds, the whole list, and expectedRevision (the settings revision).`,
	// A passkey made or used, POST /account/passkeys/finish and /auth/passkeys/finish.
	"passkeyregistrationfinishinput.credential": `The browser's WebAuthn answer to the start's challenge (navigator.credentials.create's PublicKeyCredential, as JSON): only the person's browser or device makes it, so an agent leaves adding a passkey to them.`,
	"passkeyloginfinishinput.credential":        `The browser's WebAuthn answer to the start's challenge (navigator.credentials.get's PublicKeyCredential, as JSON): only the person's browser or device makes it; an agent logs in by its own connection instead.`,
	// A content graph change's block, POST /pages/{id}/content-graph/mutations.
	"graphblock.content":     `The block's content by its type: block_contents in this answer gives each type's keys; a text block's words go in textUpdates.`,
	"graphblock.basecontent": `The content your change starts from, as GET /pages/{id}/content-graph read it: given, only the keys you changed from it go into the block as it is now, so a change made meanwhile to its other keys stays; left out, content replaces the block's whole.`,
	// A person's sidebar layout, PUT /workspaces/{workspaceId}/sidebar-layout.
	"sidebarlayout.revision": `The revision GET /workspaces/{workspaceId}/sidebar-layout reads the person's sidebar layout at (0 while they keep no layout of their own). PUT takes the whole SidebarLayout and replaces it: read it, make your change on what it is now and send all of it back with that revision. If another screen, device or agent changed it meanwhile, the PUT is refused with 409 LEAFEN_SIDEBAR_LAYOUT_REVISION_CONFLICT and nothing is lost: read it again and make the change once more. The answer holds the new revision.`,
	// A workspace's sidebar presets, PUT /workspaces/{workspaceId}/sidebar-presets.
	"sidebarpresetsresponse.revision": `The revision GET /workspaces/{workspaceId}/sidebar-presets reads the workspace's sidebar presets at (0 while it keeps none of its own). PUT, by the workspace's owners, takes all the presets and replaces them: read them, make your change on what they are now and send all of them back with that revision. If another owner, settings window or agent changed them meanwhile, the PUT is refused with 409 LEAFEN_SIDEBAR_PRESETS_REVISION_CONFLICT and nothing is lost: read them again and make the change once more. The answer holds the new revision.`,
}
